def smartNumber(n):
    sieve = [0] * 30000
    spf = [0] * 30000
    primes = []

    for i in range(2, 30000):
        if sieve[i] == 0:
            spf[i] = i
            primes.append(i)
        for prime in primes:
            if i * prime >= 30000:
                break
            sieve[i * prime] = 1
            spf[i * prime] = prime

    def find_prime_factors(x):
        factors = set()
        while x != 1:
            factors.add(spf[x])
            x //= spf[x]
        return factors

    count = 0
    i = 1
    while True:
        factors = find_prime_factors(i)
        if len(factors) == 2:
            count += 1
            if count == n:
                return i
        i += 1
